#include <sys/utsname.h>

#define PAGE_SIZE 4096
#define PIPE_BUF_SIZE 65536
#define RACE_ITERATIONS 1000

// Set pipe buffer size using F_SETPIPE_SZ
static int set_pipe_size(int pipe_fd, int size) {
    int res = fcntl(pipe_fd, F_SETPIPE_SZ, size);
    if (res == -1) {
        perror("fcntl(F_SETPIPE_SZ)");
    }
    return res;
}

// nanosleep helper for timing control
static void ns_sleep(long ns) {
    struct timespec ts = {0, ns};
